            P4MBench b;
            b.access(0x88, 1, 0);
            b.access(0xd0, 1, 0x1234);
            ck(b.access(0xd0) == 0x1234, "gap set");
            b.access(0x88, 1, 0);
            ck(b.access(0xd0) == 0, "disable zeroes gap");
            cases++;
        }

